  "inlineSchema": "// 이든 독서교육원(edenbooks) 관리 툴 — 데이터 모델\n// edenschool 운영 DB와 분리된 별도 데이터베이스(edenbooks)에서 사용.\n// 런타임 연결은 src/lib/reading/prisma.ts 의 드라이버 어댑터가 담당하고,\n// 이 스키마는 클라이언트 생성(prisma generate)과 DDL 참조용이다.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/lib/reading/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ── 사용자(선생님/원장) ────────────────────────────────\nenum UserRole {\n  ADMIN // 원장(관리자)\n  TEACHER // 담당 선생님\n  CLINIC // 클리닉 선생님\n}\n\nmodel User {\n  id           Int      @id @default(autoincrement())\n  name         String\n  email        String   @unique\n  role         UserRole @default(TEACHER)\n  active       Boolean  @default(true)\n  passwordHash String? // scrypt 해시 (로그인용)\n  createdAt    DateTime @default(now())\n\n  classes Class[] // 담당 반\n}\n\n// ── 문자 발송 로그 (알리고) ─────────────────────────────\nmodel SmsLog {\n  id            Int      @id @default(autoincrement())\n  sendId        Int      @default(0)\n  phone         String\n  message       String   @db.Text\n  type          String   @default(\"SMS\") // SMS/LMS/MMS\n  title         String?\n  resultMessage String?  @db.Text\n  success       Boolean  @default(false)\n  templateId    Int?\n  sentAt        DateTime @default(now())\n\n  @@index([sentAt])\n}\n\n// ── 반 ─────────────────────────────────────────────────\nmodel Class {\n  id        Int      @id @default(autoincrement())\n  name      String // 반 이름 (예: 목요 3:00 A반)\n  schedule  String? // 요일/시간 텍스트 (예: 월·목 15:00)\n  capacity  Int      @default(8) // 정원\n  color     String   @default(\"#6366f1\")\n  teacherId Int?\n  teacher   User?    @relation(fields: [teacherId], references: [id])\n  createdAt DateTime @default(now())\n\n  students Student[]\n}\n\n// ── 학생 ───────────────────────────────────────────────\nenum StudentStatus {\n  ENROLLED // 재원\n  PAUSED // 휴원\n  WITHDRAWN // 퇴원\n}\n\nmodel Student {\n  id           Int           @id @default(autoincrement())\n  name         String\n  grade        String // 학년 (예: 초3)\n  phone        String // 연락처(핸드폰)\n  phoneLast4   String // 뒷자리 4자리 (체크인 매칭용)\n  status       StudentStatus @default(ENROLLED)\n  registeredAt DateTime      @default(now())\n  memo         String?       @db.Text\n  classId      Int?\n  class        Class?        @relation(fields: [classId], references: [id])\n\n  attendances  Attendance[]\n  observations Observation[]\n  counsels     Counsel[]\n  corrections  Correction[]\n  clinics      Clinic[]\n\n  @@index([phoneLast4])\n  @@index([status])\n}\n\n// ── 출결 ───────────────────────────────────────────────\nenum AttendanceStatus {\n  PRESENT // 출석\n  LATE // 지각\n  ABSENT // 결석\n  MAKEUP // 보강\n}\n\nenum CheckInMethod {\n  KEYPAD // 태블릿 뒷자리 체크인\n  MANUAL // 수동 보정\n}\n\nmodel Attendance {\n  id        Int              @id @default(autoincrement())\n  studentId Int\n  student   Student          @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  date      DateTime         @db.Date // 수업일 (당일 1회 제약)\n  checkInAt DateTime         @default(now())\n  status    AttendanceStatus @default(PRESENT)\n  method    CheckInMethod    @default(KEYPAD)\n  note      String?\n\n  @@unique([studentId, date])\n  @@index([date])\n}\n\n// ── 관찰일지 (PDF 루브릭) ───────────────────────────────\n// items: [{ area, item, level: '상'|'중'|'하', text, note }]\nmodel Observation {\n  id        Int      @id @default(autoincrement())\n  studentId Int\n  student   Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  round     Int // 회차\n  date      DateTime @default(now())\n  items     Json // 관찰 항목 배열\n  memo      String?  @db.Text\n  createdAt DateTime @default(now())\n\n  counsels Counsel[]\n\n  @@index([studentId])\n}\n\n// ── 상담 기록 ──────────────────────────────────────────\nmodel Counsel {\n  id            Int          @id @default(autoincrement())\n  studentId     Int\n  student       Student      @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  date          DateTime     @default(now())\n  type          String       @default(\"정기상담\") // 상담 유형\n  content       String       @db.Text\n  nextAction    String?      @db.Text\n  nextDate      DateTime?\n  observationId Int?\n  observation   Observation? @relation(fields: [observationId], references: [id])\n  createdAt     DateTime     @default(now())\n\n  @@index([studentId])\n}\n\n// ── AI 서술형 첨삭 ─────────────────────────────────────\nenum CorrectionStatus {\n  UPLOADED // 업로드됨\n  RECOGNIZED // 인식·확정\n  DONE // 첨삭 완료\n}\n\nmodel Correction {\n  id          Int              @id @default(autoincrement())\n  studentId   Int?\n  student     Student?         @relation(fields: [studentId], references: [id])\n  title       String           @default(\"첨삭\")\n  imageUrl    String? // 원본 이미지(목업)\n  problemText String?          @db.Text // 인식된 문제\n  answerText  String?          @db.Text // 인식된 답안\n  genre       String? // 글의 종류\n  gradeLevel  String? // 첨삭 기준 학년 (초1~초6)\n  options     Json? // { tone, metrics[], custom, edenDirection }\n  scores      Json? // 척도별 점수\n  resultText  String?          @db.Text // AI 첨삭 결과(편집 가능)\n  summary     String?          @db.Text // 이든 분석지 요약(총평)\n  status      CorrectionStatus @default(UPLOADED)\n  createdAt   DateTime         @default(now())\n\n  @@index([studentId])\n}\n\n// ── 공지 템플릿 ────────────────────────────────────────\nmodel NoticeTemplate {\n  id        Int      @id @default(autoincrement())\n  title     String\n  body      String   @db.Text // {이름}{반}{점수}{특이점} 변수 포함\n  variables Json // 변수 목록\n  createdAt DateTime @default(now())\n}\n\n// ── 앱 설정 (key-value) ────────────────────────────────\nmodel AppSetting {\n  key       String   @id\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n}\n\n// ── 클리닉 시간표 ──────────────────────────────────────\nmodel Clinic {\n  id        Int      @id @default(autoincrement())\n  studentId Int\n  student   Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  weekday   Int // 1=월 ... 6=토\n  time      String // \"16:00\"\n  subject   String   @default(\"클리닉\")\n  createdAt DateTime @default(now())\n\n  @@index([weekday])\n}\n",
